private suspend fun queryParkingBrakeTelltale(): String {
    val telltales = withTimeoutOrNull(TELLTALE_TIMEOUT_MS) {
        suspendCancellableCoroutine<Telltales> { continuation ->
            telltaleVehicle.getSafety().getTelltalesInfo(
                { if (continuation.isActive) continuation.resume(it) },
                { if (continuation.isActive) continuation.resumeWithException(it) }
            )
        }
    } ?: return NO_VALUE
    return telltales.telltales
        .filter { it.type in PARKING_TELLTALES }
        .joinToString { "${it.type}=${it.state}" }
        .ifEmpty { "주차 브레이크 항목 없음 (전체 ${telltales.telltales.size}개)" }
}

