    suspend fun readBattery(): BatteryState?

    /** 계기판 누적 주행거리 변화 (km) */
    val odometerKm: Flow<Float?>

    /** 기어 위치 변화 */
    val gear: Flow<GearPosition>

    /** 주차 브레이크 상태 변화. 지원하지 않으면 null */
