    /** 정차(P)가 이 시간 동안 이어지면 미분류로 운행을 마친다 */
    var parkedTimeoutMs: Long
        get() = prefs.getLong(KEY_PARKED_TIMEOUT, DEFAULT_PARKED_TIMEOUT_MS)
