        const val KEY_CONSENT = "consent_given"
        const val KEY_VEHICLE_ID = "vehicle_id"
        const val KEY_VIN = "vin"
        const val KEY_PARKED_TIMEOUT = "parked_timeout_ms"
        const val DEFAULT_PARKED_TIMEOUT_MS = 5 * 60_000L
    }
}

